<?php

declare(strict_types=1);
require_once __DIR__.'/issuers/IssuerStorage.php';
require_once __DIR__.'/issuers/IssuerTransaction.php';
require_once __DIR__.'/issuers/IssuerResourceAccess.php';

/** Five shipped Unicode font families only; no filenames, uploads, hooks or global font inheritance. */
final class CompanyPdfTypography
{
    private const NODE='pdf_typography_preferences';
    public const FIELDS=['pdf_font','pdf_font_size'];
    public function __construct(private$db,private string$p){if(!preg_match('/^[A-Za-z0-9_]+$/D',$p))throw new InvalidArgumentException('Invalid prefix');}
    public static function fonts():array{return ['dejavusans'=>'DejaVu Sans','dejavuserif'=>'DejaVu Serif','dejavusansmono'=>'DejaVu Sans Mono','freesans'=>'Free Sans','freeserif'=>'Free Serif'];}
    public static function prepare(array$settings):array{if(array_keys($settings)!==self::FIELDS||!is_string($settings['pdf_font'])||!isset(self::fonts()[$settings['pdf_font']])||!is_string($settings['pdf_font_size'])||($settings['pdf_font_size']!==''&&!preg_match('/^(?:[6-9]|1[0-9]|2[0-4])$/D',$settings['pdf_font_size'])))throw new DomainException('company_pdf_typography_invalid');return$settings;}
    /** Snapshot payload: typed exact font/point-size. */
    public static function validate($profile):array{if(!is_array($profile)||array_keys($profile)!==['font','size']||!is_string($profile['font'])||!isset(self::fonts()[$profile['font']])||!is_int($profile['size'])||$profile['size']<6||$profile['size']>24)throw new DomainException('company_pdf_typography_invalid');return$profile;}
    public static function historical(string$kind):array{if(!in_array($kind,['invoices','creditnotes','contracts','estimates','proposals'],true))throw new DomainException('company_pdf_typography_invalid');return ['font'=>'dejavusans','size'=>in_array($kind,['invoices','creditnotes'],true)?9:10];}
    private static function document(string$json):object{try{$doc=json_decode($json,false,32,JSON_THROW_ON_ERROR);}catch(Throwable$e){throw new DomainException('company_pdf_typography_invalid');}if(!$doc instanceof stdClass)throw new DomainException('company_pdf_typography_invalid');if(property_exists($doc,self::NODE)){$pref=$doc->{self::NODE};if(!$pref instanceof stdClass||array_keys(get_object_vars($pref))!==['format','revision','pdf_font','pdf_font_size']||$pref->format!==1||!is_int($pref->revision)||$pref->revision<1||$pref->revision>2147483647)throw new DomainException('company_pdf_typography_invalid');self::prepare(['pdf_font'=>$pref->pdf_font,'pdf_font_size'=>$pref->pdf_font_size]);}return$doc;}
    private function row(int$issuer):array{$row=IssuerStorage::query($this->db,'SELECT id,active,settings_json FROM '.$this->p.'issuers_registry WHERE id=?',[$issuer])->row_array();if(!$row||(int)$row['active']!==1)throw new DomainException('company_pdf_typography_denied');return$row;}
    /** Explicit-owner internal read. Financial creators already own their canonical transaction/issuer lock. */
    public static function capture($db,string$p,int$issuer,string$kind):?array{$self=new self($db,$p);$issuer=IssuerPolicy::id($issuer);$defaults=self::historical($kind);$pref=self::document((string)$self->row($issuer)['settings_json'])->{self::NODE}??null;return$pref?self::validate(['font'=>$pref->pdf_font,'size'=>$pref->pdf_font_size===''?$defaults['size']:(int)$pref->pdf_font_size]):null;}
    public function tables():array{return ['issuers_lock','issuers_registry','issuers_installation_identity','issuers_staff','issuers_resource_permissions','staff','issuers_audit'];}
    private function authorize(int$issuer,int$actor,string$cap):void{if(!(new IssuerResourceAccess($this->db,$this->p))->can($issuer,$actor,'settings',$cap))throw new DomainException('company_pdf_typography_denied');}
    public function page($issuer,$actor):array{$issuer=IssuerPolicy::id($issuer);$actor=IssuerPolicy::id($actor);$this->authorize($issuer,$actor,'view');return IssuerTransaction::run($this->db,$this->p,$this->tables(),function()use($issuer,$actor){$this->authorize($issuer,$actor,'view');$pref=self::document((string)$this->row($issuer)['settings_json'])->{self::NODE}??null;return ['revision'=>$pref?->revision??0,'pdf_font'=>$pref?->pdf_font??'dejavusans','pdf_font_size'=>$pref?->pdf_font_size??''];});}
    public function save($issuer,$actor,int$revision,array$settings):void{$issuer=IssuerPolicy::id($issuer);$actor=IssuerPolicy::id($actor);self::prepare($settings);if($revision<0||$revision>=2147483647)throw new DomainException('company_pdf_typography_invalid');$this->authorize($issuer,$actor,'edit');IssuerTransaction::run($this->db,$this->p,$this->tables(),function()use($issuer,$actor,$revision,$settings){$this->authorize($issuer,$actor,'edit');$doc=self::document((string)$this->row($issuer)['settings_json']);$old=$doc->{self::NODE}??null;if(($old?->revision??0)!==$revision)throw new DomainException('company_pdf_typography_stale');if($old&&$old->pdf_font===$settings['pdf_font']&&$old->pdf_font_size===$settings['pdf_font_size'])return;$doc->{self::NODE}=(object)(['format'=>1,'revision'=>$revision+1]+$settings);$json=json_encode($doc,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);IssuerStorage::query($this->db,'UPDATE '.$this->p.'issuers_registry SET settings_json=? WHERE id=?',[$json,$issuer]);if((string)$this->row($issuer)['settings_json']!==$json)throw new RuntimeException('issuer_pdf_typography_write_unconfirmed');$now=date('Y-m-d H:i:s');IssuerStorage::query($this->db,'INSERT INTO '.$this->p.'issuers_audit(actor_id,event,issuer_id,subject_id,created_at) VALUES(?,?,?,NULL,?)',[$actor,'company_pdf_typography_saved',$issuer,$now]);$id=(int)$this->db->insert_id();if(!IssuerStorage::query($this->db,'SELECT id FROM '.$this->p.'issuers_audit WHERE id=? AND actor_id=? AND event=? AND issuer_id=? AND subject_id IS NULL AND created_at=?',[$id,$actor,'company_pdf_typography_saved',$issuer,$now])->row_array())throw new RuntimeException('issuer_pdf_typography_write_unconfirmed');$this->authorize($issuer,$actor,'edit');});}
}
